(assert (= "1.12.6" (clojure-version)))
(let [source "(let [x 1.25 f (fn [] (+ x 2.0))] ((identity f)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "3.25" actual)))
(let [source "(let [x 3000000000 f (fn again [n] (if (= n 0) (+ x 1) (again (- n 1))))] (f 3))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "3000000001" actual)))
(let [source "(let [x 3000000000 f (fn ([] (+ x 1)) ([a] (+ x 2)))] [(f) (f :unused)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3000000001 3000000002]" actual)))
(let [source "(let [x 1.25 f (fn [& xs] (+ x 2.0))] [(f) (f :a :b)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3.25 3.25]" actual)))
(let [source "(let [x 1.25 f (fn ^double [] (+ x 2.0))] [(f) ((identity f))])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3.25 3.25]" actual)))
(let [source "(let [x -0.0 f (fn [] (* x 2.0))] [(f) (/ 1.0 (f))])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[-0.0 ##-Inf]" actual)))
(let [source "(let [x ##NaN f (fn [] (+ x 1.0)) a (f) b (f)] [(= a b) (== a b) (identical? a b)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[false false false]" actual)))
(let [source "(let [x 9223372036854775807 f (fn [] (+ x 1))] (try (f) (catch Throwable e (ex-message e))))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "\"long overflow\"" actual)))
(let [source "(let [x 127.1 f (fn [] x)] (byte ((identity f))))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "127" actual)))
(let [source "(let [x 2147483648.0 f (fn [] (+ x 0.0))] (try (int ((identity f))) (catch Throwable e :error)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= ":error" actual)))
(let [source "(let [x 3000000000 f (fn [] x)] (identical? ((identity f)) ((identity f))))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "true" actual)))
(let [source "(let [x 1.5 f (fn [b] (if b x x))] [(f true) (f false)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[1.5 1.5]" actual)))
(let [source "(let [x 3000000000 f (fn ([] (+ x 1)) ([a] x))] [(f) (identical? (f :a) (f :b))])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3000000001 true]" actual)))
(let [source "(let [x 3000000000 f (fn [] (fn [] x)) g ((identity f))] [(g) (identical? (g) (g))])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3000000000 true]" actual)))
(let [source "(let [x 1.5 f (with-meta (fn [] (+ x 2.0)) {:tag :kept})] [(f) (:tag (meta f))])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3.5 :kept]" actual)))
(let [source "(let [events (atom []) x (do (swap! events conj :capture) 1.5) f (fn [] (do (swap! events conj :body) (+ x 2.0)))] [(f) (f) @events])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3.5 3.5 [:capture :body :body]]" actual)))
(let [source "(let [x 1.5 f (fn [] (+ x 2.0))] [(f) (try (f 1) (catch Throwable e :arity)) (f)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3.5 :arity 3.5]" actual)))
(let [source "(let [x 1.5 f (fn [] (+ x 2.0)) out (atom f)] [(@out) (fn? @out)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3.5 true]" actual)))
